func dtSurvive(pdf *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, pg *port.Cells, out *port.Cells) int32 {
	// Open, list the pages, and decode every stream the cross-reference
	// names: none of it may fault. Answers the pd-open status.
	var status int32 = dtOpen(pdf, ar, dc, a, b, st, pg)
	var i int32 = 1
	var h int32 = 0
	if status == 0 {
		for i < pdfdoc.PdObjectCount(dc) {
			h = pdfdoc.PdGet(pdf, ar, dc, a, b, st, i)
			if h != 0 {
				if pdflex.PlKindOf(ar, h) == 8 {
					pdfdoc.PdStreamData(pdf, ar, dc, a, b, st, h, out)
				}
			}
			i += 1
		}
	}
	return status
}

func dtCut(f []byte, n int32, cut *port.Cells) int32 {
	// cut = the first n bytes of f.
	var i int32 = 0
	port.CellsDrop(cut, 0)
	for i < n {
		port.CellsPush(cut, port.BlobU8(f, i))
		i += 1
	}
	return n
}

func dtTruncations(f []byte, step int32, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, pg *port.Cells, out *port.Cells, cut *port.Cells) int32 {
	// Every truncation of f (every `step` bytes): none may fault. Answers
	// how many still opened.
	var n int32 = port.BlobLen(f)
	var k int32 = 0
	var ok int32 = 0
	for k <= n {
		dtCut(f, k, cut)
		if dtSurvive(port.SrcOfBlob(port.CellsBlob(cut)), ar, dc, a, b, st, pg, out) == 0 {
			ok += 1
		}
		k += step
	}
	return ok
}

func dtCorruptions(f []byte, rounds int32, flips int32, seed int32, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, pg *port.Cells, out *port.Cells, cut *port.Cells, rng *port.Cells) int32 {
	// `rounds` copies of f, each with `flips` random bytes replaced
	// (SplitMix, so every target damages the same bytes): none may fault.
	var n int32 = port.BlobLen(f)
	var r int32 = 0
	var j int32 = 0
	var at int32 = 0
	var ok int32 = 0
	splitmix.SmSeed(rng, int64(seed))
	for r < rounds {
		dtCut(f, n, cut)
		j = 0
		for j < flips {
			at = splitmix.SmBelow(rng, n)
			port.CellsSet(cut, at, splitmix.SmBelow(rng, 256))
			j += 1
		}
		if dtSurvive(port.SrcOfBlob(port.CellsBlob(cut)), ar, dc, a, b, st, pg, out) == 0 {
			ok += 1
		}
		r += 1
	}
	return ok
}

func TestNoTruncationOfAFixtureFaults(emonT *testing.T) {
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var cut *port.Cells = port.NewCells()
	// Every byte of the small file, and the whole of each other: none may
	// fault. With repair by scanning (P3.1) a cut opens as soon as it holds
	// the catalog and the page tree: minimal.pdf's second object ends at 110,
	// and a cut at 103, before its `endobj`, still parses.
	port.AssertEq(emonT, dtTruncations(port.TestFile("pdf/minimal.pdf"), 1, ar, dc, a, b, st, pg, out, cut), 457, "minimal: every cut from 103 bytes on (560 bytes: 457 cuts)")
	port.AssertThat(emonT, dtTruncations(port.TestFile("pdf/xrefstream.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "xref stream file")
	port.AssertThat(emonT, dtTruncations(port.TestFile("pdf/hybrid.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "hybrid file")
	port.AssertThat(emonT, dtTruncations(port.TestFile("pdf/incremental.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "incremental file")
	port.AssertThat(emonT, dtTruncations(port.TestFile("pdf/filters.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "filters file")
}

